import{_ as o,c as t,o as i,ag as a}from"./chunks/framework.DZ_cNctr.js";const d=JSON.parse('{"title":"Video script — Analytics & Phenotyping","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/analytics-phenotyping-video.md","filePath":"scripts/analytics-phenotyping-video.md"}'),l={name:"scripts/analytics-phenotyping-video.md"};function r(n,e,s,c,h,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="video-script-—-analytics-phenotyping" tabindex="-1">Video script — Analytics &amp; Phenotyping <a class="header-anchor" href="#video-script-—-analytics-phenotyping" aria-label="Permalink to &quot;Video script — Analytics &amp; Phenotyping&quot;">​</a></h1><p><strong>Target length</strong>: ~2 minutes (this one earns more time than annotations — the phenotype flow is the payoff) <strong>Audience</strong>: Cell biologists with CellProfiler / QuPath / CP exports sitting on disk <strong>Call to action</strong>: Try it with your own CSV</p><hr><h2 id="cold-open-0-00-–-0-10" tabindex="-1">Cold open (0:00 – 0:10) <a class="header-anchor" href="#cold-open-0-00-–-0-10" aria-label="Permalink to &quot;Cold open (0:00 – 0:10)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>A WSI with segmentation overlay visible, all cells in a single flat color (orange, say).</li><li>Pause 1 second.</li><li>Cut: same image, cells now colored by phenotype — Small/Mid/Large in blue/orange/red. Legend card in the corner.</li><li>Pause 1 second.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Segmentation is the hard part. Find Nuclei Viewer colors it by whatever measurement you care about — area, intensity, shape — and groups cells into named phenotypes. All in the browser. All interactive.&quot;</p></blockquote><hr><h2 id="load-a-csv-0-10-–-0-30" tabindex="-1">Load a CSV (0:10 – 0:30) <a class="header-anchor" href="#load-a-csv-0-10-–-0-30" aria-label="Permalink to &quot;Load a CSV (0:10 – 0:30)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Labels tab open in sidebar. Click a label row — it expands.</li><li>Analytics section visible with &quot;Load CSV&quot; button.</li><li>Click. OS file picker opens briefly.</li><li>Pick <code>nuclei-measurements.csv</code>.</li><li>Analytics section updates: &quot;nuclei-measurements.csv · 329 obj · 12 col&quot;.</li><li>Click the info (ⓘ) button. Modal opens showing columns with min/max/mean statistics.</li><li>Close modal.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Any per-object CSV from CellProfiler, QuPath, FIJI, or napari works. The viewer auto-detects the object-ID column, profiles every column, and shows you the stats. No server, no upload — your data stays on your machine.&quot;</p></blockquote><hr><h2 id="color-by-column-—-heatmap-0-30-–-0-50" tabindex="-1">Color by column — heatmap (0:30 – 0:50) <a class="header-anchor" href="#color-by-column-—-heatmap-0-30-–-0-50" aria-label="Permalink to &quot;Color by column — heatmap (0:30 – 0:50)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Click the color swatch on the label row. Popover opens.</li><li>Click &quot;Heatmap&quot; tab.</li><li>Dropdown: select <code>area_px</code>.</li><li>Ramp dropdown: switch between viridis → magma → coolwarm. Canvas re-colors in real time.</li><li>A histogram with a dual-range slider appears. Drag the max handle left — the contrast tightens on mid-range cells, outliers collapse to the top color.</li><li>Close popover.</li><li>Canvas shows cells in a smooth viridis gradient. Legend in bottom-right shows the ramp with min/max labels.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Heatmap mode — pick a numeric column, pick a ramp. Viridis is the default because it&#39;s perceptually uniform, but magma, inferno, coolwarm, and turbo are all here. If outliers compress your signal, override the range with the slider.&quot;</p></blockquote><hr><h2 id="filters-0-50-–-1-10" tabindex="-1">Filters (0:50 – 1:10) <a class="header-anchor" href="#filters-0-50-–-1-10" aria-label="Permalink to &quot;Filters (0:50 – 1:10)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Scroll to the Filters section. Click &quot;+ Add filter&quot;.</li><li>Popover lists columns. Pick <code>eccentricity</code>.</li><li>Filter row appears with a histogram. Drag the left handle in — elongated cells disappear from the canvas.</li><li>Click &quot;+ Add filter&quot; again. Pick a string column, say <code>is_mitotic</code>.</li><li>Two checkboxes: &quot;true&quot; and &quot;false&quot;. Uncheck &quot;false&quot; — only mitotic cells visible.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Filters hide cells that don&#39;t match. Numeric columns get a range slider. String columns get checkboxes. Multiple filters compose with AND — every filter must pass.&quot;</p></blockquote><hr><h2 id="phenotypes-1-10-–-1-45" tabindex="-1">Phenotypes (1:10 – 1:45) <a class="header-anchor" href="#phenotypes-1-10-–-1-45" aria-label="Permalink to &quot;Phenotypes (1:10 – 1:45)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Remove the two filters (click × on each).</li><li>Scroll to Phenotypes. Click &quot;+ Add phenotype&quot;.</li><li>A new group &quot;Phenotype 1&quot; appears. Click the name — rename to &quot;Small&quot;.</li><li>Click the swatch — pick blue from the preset grid.</li><li>Click &quot;+ Add filter&quot; inside the group. Pick <code>area_px</code>. Drag range slider to low end.</li><li>Canvas immediately colors small cells blue.</li><li>Add two more phenotypes: &quot;Mid&quot; (orange), &quot;Large&quot; (red). Each with an area_px range.</li><li>Scroll up. Canvas now shows three-color phenotype overlay.</li><li>Legend bottom-right updates with Small / Mid / Large rows.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Phenotypes turn filters into named populations. Give the group a name, a color, and conditions — filter by area, by intensity, by a category column, or any combination. First match wins, so reorder by dragging to get the logic right.&quot;</p></blockquote><hr><h2 id="show-unmatched-palette-toggle-1-45-–-1-55" tabindex="-1">Show unmatched + palette toggle (1:45 – 1:55) <a class="header-anchor" href="#show-unmatched-palette-toggle-1-45-–-1-55" aria-label="Permalink to &quot;Show unmatched + palette toggle (1:45 – 1:55)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Toggle &quot;Show unmatched objects (gray)&quot; off — a handful of grayed cells disappear.</li><li>Toggle it back on.</li><li>Colors toggle: &quot;Assigned → Palette&quot;. The three groups swap to Tableau colors.</li><li>Flip back to &quot;Assigned&quot;.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Unmatched cells show in gray for context, or hide entirely. Colors come from your own palette, or from a built-in categorical one.&quot;</p></blockquote><hr><h2 id="persistence-and-sharing-1-55-–-2-10" tabindex="-1">Persistence and sharing (1:55 – 2:10) <a class="header-anchor" href="#persistence-and-sharing-1-55-–-2-10" aria-label="Permalink to &quot;Persistence and sharing (1:55 – 2:10)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Click somewhere on the toolbar — the share link icon. A share modal or copied-to-clipboard toast.</li><li>Reload the page (show the reload).</li><li>CSV still loaded, phenotypes still active, view restored.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Everything persists in your browser. Reload, come back tomorrow, pick up where you left off. Share a link and a reviewer opens the same image with the same colors — annotations and view state come along in the URL.&quot;</p></blockquote><hr><h2 id="close-2-10-–-2-20" tabindex="-1">Close (2:10 – 2:20) <a class="header-anchor" href="#close-2-10-–-2-20" aria-label="Permalink to &quot;Close (2:10 – 2:20)&quot;">​</a></h2><p><strong>Visual</strong>: Final shot of the image with the phenotype overlay, legend visible, fullscreen.</p><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Open it at find-nuclei dot github dot io. Your CSV, your image, your classification — in thirty seconds.&quot;</p></blockquote><p><strong>On-screen text</strong>: <code>find-nuclei.github.io</code></p><hr><h2 id="production-notes" tabindex="-1">Production notes <a class="header-anchor" href="#production-notes" aria-label="Permalink to &quot;Production notes&quot;">​</a></h2><ul><li><strong>CSV choice</strong>: use a CellProfiler <code>Nuclei.csv</code> or similar — real-world, with recognizable column names like <code>AreaShape_Area</code>, <code>Intensity_MeanIntensity_DAPI</code>.</li><li><strong>Pre-load the image</strong> so the cold open doesn&#39;t spend time on loading screens. You can edit a clean re-take of the image into the intro.</li><li><strong>Ramp tour</strong>: when cycling ramps, space them by ~1 second each so viewers can see the visual difference.</li><li><strong>Don&#39;t over-explain</strong>: the voiceover assumes the viewer understands what segmentation is. If we need a 101 explainer, that&#39;s a separate video.</li><li><strong>Phenotype demo data</strong>: pre-figure out three groups that segment cleanly — Small &lt; 100 px², Mid 100-500, Large &gt; 500 — so the phenotype demo has obvious visual separation.</li></ul><h2 id="thumbnail-candidates" tabindex="-1">Thumbnail candidates <a class="header-anchor" href="#thumbnail-candidates" aria-label="Permalink to &quot;Thumbnail candidates&quot;">​</a></h2><ol><li>The before/after split at 0:00-0:10 — flat orange → phenotype-colored</li><li>The legend card close-up with the three phenotype swatches</li><li>The multi-filter mid-shot showing the histogram + slider</li></ol>',55)])])}const g=o(l,[["render",r]]);export{d as __pageData,g as default};
